#!/usr/bin/env python

"""Time humanizing functions.

These are largely borrowed from Django's `contrib.humanize`.
"""

import datetime as dt
import math
from enum import Enum
from functools import total_ordering
from typing import Optional, Union

from .i18n import gettext as _
from .i18n import ngettext

__all__ = [
    "naturaldelta",
    "naturaltime",
    "naturalday",
    "naturaldate",
    "precisedelta",
]


@total_ordering
class Unit(Enum):
    MICROSECONDS = 0
    MILLISECONDS = 1
    SECONDS = 2
    MINUTES = 3
    HOURS = 4
    DAYS = 5
    MONTHS = 6
    YEARS = 7

    def __lt__(self, other):
        if self.__class__ is other.__class__:
            return self.value < other.value
        return NotImplemented


def _now() -> dt.datetime:
    return dt.datetime.now()


def abs_timedelta(delta: dt.timedelta) -> dt.timedelta:
    """Return an "absolute" value for a timedelta, always representing a time distance.

    Args:
        delta (datetime.timedelta): Input timedelta.

    Returns:
        datetime.timedelta: Absolute timedelta.
    """
    if delta.days < 0:
        now = _now()
        return now - (now + delta)
    return delta


def date_and_delta(
    value: Union[dt.datetime, dt.timedelta, str, int], *, now: Optional[dt.datetime] = None
) -> tuple:
    """Turn a value into a date and a timedelta which represents how long ago it was.

    If that's not possible, return `(None, value)`.
    """
    if not now:
        now = _now()
    if isinstance(value, dt.datetime):
        date = value
        delta = now - value
    elif isinstance(value, dt.timedelta):
        date = now - value
        delta = value
    else:
        try:
            value = int(value)
            delta = dt.timedelta(seconds=value)
            date = now - delta
        except (ValueError, TypeError):
            return None, value
    return date, abs_timedelta(delta)


def naturaldelta(
    value: Union[dt.datetime, dt.timedelta, str, int],
    months: bool = True,
    minimum_unit: str = "seconds",
    when: Optional[dt.datetime] = None,
) -> str:
    """Return a natural representation of a timedelta or number of seconds.

    This is similar to `naturaltime`, but does not add tense to the result.

    Args:
        value (datetime.timedelta): A timedelta or a number of seconds.
        months (bool): If `True`, then a number of months (based on 30.5 days) will be
            used for fuzziness between years.
        minimum_unit (str): The lowest unit that can be used.
        when (datetime.datetime): Point in time relative to which _value_ is
            interpreted.  Defaults to the current time in the local timezone.

    Returns:
        str: A natural representation of the amount of time elapsed.

    Examples
        Compare two timestamps in a custom local timezone::

        import datetime as dt
        from dateutil.tz import gettz

        berlin = gettz("Europe/Berlin")
        now = dt.datetime.now(tz=berlin)
        later = now + dt.timedelta(minutes=30)

        assert naturaldelta(later, when=now) == "30 minutes"
    """
    tmp = Unit[minimum_unit.upper()]
    if tmp not in (Unit.SECONDS, Unit.MILLISECONDS, Unit.MICROSECONDS):
        raise ValueError(f"Minimum unit '{minimum_unit}' not supported")
    minimum_unit = tmp

    date, delta = date_and_delta(value, now=when)
    if date is None:
        return value

    use_months = months

    seconds = abs(delta.seconds)
    days = abs(delta.days)
    years = days // 365
    days = days % 365
    months = int(days // 30.5)

    if not years and days < 1:
        if seconds == 0:
            if minimum_unit == Unit.MICROSECONDS and delta.microseconds < 1000:
                return (
                    ngettext("%d microsecond", "%d microseconds", delta.microseconds)
                    % delta.microseconds
                )
            elif minimum_unit == Unit.MILLISECONDS or (
                minimum_unit == Unit.MICROSECONDS
                and 1000 <= delta.microseconds < 1_000_000
            ):
                milliseconds = delta.microseconds / 1000
                return (
                    ngettext("%d millisecond", "%d milliseconds", milliseconds)
                    % milliseconds
                )
            return _("a moment")
        elif seconds == 1:
            return _("a second")
        elif seconds < 60:
            return ngettext("%d second", "%d seconds", seconds) % seconds
        elif 60 <= seconds < 120:
            return _("a minute")
        elif 120 <= seconds < 3600:
            minutes = seconds // 60
            return ngettext("%d minute", "%d minutes", minutes) % minutes
        elif 3600 <= seconds < 3600 * 2:
            return _("an hour")
        elif 3600 < seconds:
            hours = seconds // 3600
            return ngettext("%d hour", "%d hours", hours) % hours
    elif years == 0:
        if days == 1:
            if use_months:
                return _("a day")
            return _("1 day")
        elif days < 4 and use_months and not months:
            return _("{} days".format(days))

        if days <= 1:
            return ngettext("%d day", "%d days", days) % days
        elif 60 <= (days / 30.5) < 2:
            return _("a month")
        elif 60 <= (days / 30.5) < 365 and not use_months:
            months = int(days / 30.5)
            return ngettext("%d month", "%d months", months) % months
        elif 365 < days < 365 * 2:
            return _("over a year")
        elif use_months:
            months = int(days / 30.5)
            return ngettext("%d month", "%d months", months) % months
        else:
            return "{} days".format(days)
    elif years == 1:
        if not days:
            return _("a year")
        elif days == 1:
            return _("1 year, 1 day")
        elif use_months:
            return _("{} year, {} month".format(years, months))
        else:
            return _("{} year, {} days".format(years, days))
    elif use_months:
        months = int(days / 30.5)
        return ngettext("%d year", "%d years", years).format(
            years,
        ) + ", {} month{}".format(
            months,
            "" if months == 1 else "s",
        )
    else:
        return ngettext("%d year", "%d years", years).format(years)


def naturaltime(
    value: Union[dt.datetime, dt.timedelta, str, int],
    now: Optional[dt.datetime] = None,
    reference: Optional[str] = None,
    months: bool = True,
    minimum_unit: str = "seconds",
    when: Optional[dt.datetime] = None,
) -> str:
    """Return a natural representation of a date and time.

    Specify reference paramater as one of the 'now' (default) to express
    the output in future/past tense relative to now, another datetime in
    ISO 8601 or RFC 2822 format, as a UTC offset in the format of '+HH:MM',
    or as a string in those formats using reference=['whatever'] to specify
    the relative tense/premise.

    Args:
        value (datetime.datetime, datetime.timedelta, str, int): A datetime or a number of seconds.
        now (datetime.datetime): Point in time relative to which _value_ is
            interpreted.  Defaults to the current time in the local timezone.
        reference (str): Point in time relative to which _value_ is
            interpreted.  Defaults to 'now'.
        months (bool): If `True`, then a number of months (based on 30.5 days) will be
            used for fuzziness between years.
        minimum_unit (str): The lowest unit that can be used.
        when (datetime.datetime): Point in time relative to which _value_ is
            interpreted.  Defaults to the current time in the local timezone.

    Returns:
        str: A natural representation of the input in relative time.
    """
    fn = {
        "now": lambda d: d > 0,
        "then": lambda d: d < 0,
    }
    if reference:
        # reference=['whatever']
        if isinstance(reference, list):
            reference = reference[0]
        if reference not in fn:
            raise ValueError("Unknown reference message '{}'".format(reference))
        past = fn[reference](abs_timedelta(date_and_delta(value)[1]).total_seconds())
    else:
        # default behavior
        date, delta = date_and_delta(value, now=when)
        if date is None:
            return value
        past = delta.total_seconds() < 0

    s = naturaldelta(value, months, minimum_unit, when)
    if past:
        return _("{} from now").format(s)
    else:
        return _("{} ago").format(s)


def naturalday(value: Union[dt.date, str], format: str = "{0}") -> str:
    """Return a natural day.

    For example:

        ```pycon
        >>> naturalday(dt.date.today()) == dt.date.today().strftime('%d')
        True
        >>> naturalday(dt.date(2023, 1, 1))
        '01'

        ```

    Args:
        value (date): date object to convert to a natural day.
        format (str): Format string for outputting the day.

    Returns:
        str: A natural day formatted string.
    """
    if value is None:
        return ""
    try:
        value = dt.date.fromisoformat(value) if isinstance(value, str) else value
    except (ValueError, TypeError):
        return value
    return value.strftime(format)


def naturaldate(value: Union[dt.date, str], format: str = "{0}") -> str:
    """Like naturalday, but for dates."""
    return naturalday(value, format)


def precisedelta(
    value: Union[dt.timedelta, int, float],
    minimum_unit: str = "seconds",
    suppress: str = "",
    format: str = "%0.2f",
) -> str:
    """Return a precise representation of a timedelta.

    Specify a time delta, or a number of seconds, and get a precise string
    representation, with a matching plural or singular, e.g. "1 second", or
    "2 days, 3 hours, 4 minutes, 5 seconds".

    Arguments:
        value (timedelta): A timedelta.
        minimum_unit (str): The lowest unit to use (seconds, milliseconds, microseconds).
        suppress (list): List of units to suppress.
        format (str): Formatter to use for formatting numerical values. Default is "%0.2f".

    Returns:
        str: Precise representation of the timedelta.

    Examples:
        ```pycon
        >>> import datetime as dt
        >>> delta = dt.timedelta(seconds=30.5, minutes=4, hours=2)
        >>> precisedelta(delta)
        '2 hours, 4 minutes, 30.50 seconds'
        >>> precisedelta(delta, minimum_unit='milliseconds')
        '2 hours, 4 minutes, 30,500 milliseconds'
        >>> precisedelta(delta, suppress=['hours'])
        '4 minutes, 30.50 seconds'

        ```
    """
    unit = Unit[minimum_unit.upper()]

    if isinstance(value, (int, float)):
        value = dt.timedelta(seconds=value)

    # Get absolute value in case lower than 0
    delta = abs_timedelta(value)

    # Store total microseconds for easy calculation
    usecs = delta.total_seconds() * 1e6

    # Calculate years, months, days, hours, minutes, seconds, milliseconds, microseconds
    usecs = int(usecs)  # chop off fractional microseconds
    secs, usecs = divmod(usecs, 1000000)
    mins, secs = divmod(secs, 60)
    hours, mins = divmod(mins, 60)
    days, hours = divmod(hours, 24)
    months, days = divmod(days, 30.5)
    years, months = divmod(months, 12)

    # Keep track of units for formatting
    MICROSECONDS, MILLISECONDS, SECONDS, MINUTES, HOURS, DAYS, MONTHS, YEARS = list(
        Unit
    )

    # Given DAYS compute YEARS and the remainder of DAYS as follows:
    #   if YEARS is the minimum unit, we cannot use DAYS so
    #   we will use a float for YEARS and 0 for DAYS:
    #       years, days = years/days, 0
    #
    #   if YEARS is suppressed, use DAYS:
    #       years, days = 0, days
    #
    #   otherwise:
    #       years, days = divmod(years, days)
    #
    # The same applies for months, hours, minutes and milliseconds below
    years, days = _quotient_and_remainder(days, 365, YEARS, min(unit, YEARS), suppress)
    months, days = _quotient_and_remainder(days, 30.5, MONTHS, min(unit, MONTHS), suppress)

    # If DAYS is not in suppress, we can represent the days but
    # if it is a suppressed unit, we need to carry it to a lower unit,
    # seconds in this case.
    #
    # The same applies for secs and usecs below
    days, secs = _carry(days, secs, 24 * 3600, DAYS, min(unit, DAYS), suppress)

    hours, secs = _quotient_and_remainder(secs, 3600, HOURS, min(unit, HOURS), suppress)
    minutes, secs = _quotient_and_remainder(secs, 60, MINUTES, min(unit, MINUTES), suppress)

    secs, usecs = _carry(secs, usecs, 1e6, SECONDS, min(unit, SECONDS), suppress)

    msecs, usecs = _quotient_and_remainder(
        usecs, 1000, MILLISECONDS, min(unit, MILLISECONDS), suppress
    )

    # if _unused != 0 we had lost some precision
    usecs, _unused = _carry(usecs, 0, 1, MICROSECONDS, min(unit, MICROSECONDS), suppress)

    fmts = [
        ("%d year", "%d years", years),
        ("%d month", "%d months", months),
        ("%d day", "%d days", days),
        ("%d hour", "%d hours", hours),
        ("%d minute", "%d minutes", minutes),
        ("%d second", "%d seconds", secs),
        ("%d millisecond", "%d milliseconds", msecs),
        ("%d microsecond", "%d microseconds", usecs),
    ]

    texts = []
    for unit_idx, fmt in zip(reversed(Unit), fmts):
        singular_txt, plural_txt, val = fmt
        if val > 0 or (not texts and unit_idx == unit):
            fmt_txt = ngettext(singular_txt, plural_txt, val)
            if unit_idx == unit and math.modf(val)[0] > 0:
                fmt_txt = fmt_txt.replace("%d", format)

            texts.append(fmt_txt % val)

        if unit_idx == unit:
            break

    if len(texts) == 1:
        return texts[0]

    head = ", ".join(texts[:-1])
    tail = texts[-1]

    return _("%s and %s") % (head, tail)


def _quotient_and_remainder(value, divisor, unit, min_unit, suppress):
    if unit == min_unit:
        # Use float for the minimum unit
        return value / divisor, 0
    elif unit in suppress:
        # Suppress this unit, pass everything to lower unit
        return 0, value
    else:
        return divmod(value, divisor)


def _carry(value, sub_value, divisor, unit, min_unit, suppress):
    if unit in suppress:
        # Carry this unit to the next lower unit
        return 0, value * divisor + sub_value
    else:
        return value, sub_value
